32	/// A web device that supports a chromium browser.
33	abstract class ChromiumDevice extends Device {
34	  ChromiumDevice({
35	    @required String name,
36	    @required this.chromeLauncher,
37	    @required FileSystem fileSystem,
38	    @required Logger logger,
39	  }) : _fileSystem = fileSystem,
40	       _logger = logger,
41	       super(
42	         name,
43	         category: Category.web,
44	         platformType: PlatformType.web,
45	         ephemeral: false,
46	       );
47	
48	  final ChromiumLauncher chromeLauncher;
49	
50	  final FileSystem _fileSystem;
51	  final Logger _logger;
52	
53	  /// The active chrome instance.
54	  Chromium _chrome;
55	
56	  // TODO(jonahwilliams): this is technically false, but requires some refactoring
57	  // to allow hot mode restart only devices.
58	  @override
59	  bool get supportsHotReload => true;
60	
61	  @override
62	  bool get supportsHotRestart => true;
63	
64	  @override
65	  bool get supportsStartPaused => true;
66	
67	  @override
68	  bool get supportsFlutterExit => false;
69	
70	  @override
71	  bool get supportsScreenshot => false;
72	
73	  @override
74	  void clearLogs() { }
75	
76	  DeviceLogReader _logReader;
77	
78	  @override
79	  DeviceLogReader getLogReader({
80	    ApplicationPackage app,
81	    bool includePastLogs = false,
82	  }) {
83	    return _logReader ??= NoOpDeviceLogReader(app?.name);
84	  }
85	
86	  @override
87	  Future<bool> installApp(ApplicationPackage app) async => true;
88	
89	  @override
90	  Future<bool> isAppInstalled(ApplicationPackage app) async => true;
91	
92	  @override
93	  Future<bool> isLatestBuildInstalled(ApplicationPackage app) async => true;
94	
95	  @override
96	  Future<bool> get isLocalEmulator async => false;
97	
98	  @override
99	  Future<String> get emulatorId async => null;
100	
101	  @override
102	  bool isSupported() =>  chromeLauncher.canFindExecutable();
103	
104	  @override
105	  DevicePortForwarder get portForwarder => const NoOpDevicePortForwarder();
106	
107	  @override
108	  Future<LaunchResult> startApp(
109	    covariant WebApplicationPackage package, {
110	    String mainPath,
111	    String route,
112	    DebuggingOptions debuggingOptions,
113	    Map<String, Object> platformArgs,
114	    bool prebuiltApplication = false,
115	    bool ipv6 = false,
116	  }) async {
117	    // See [ResidentWebRunner.run] in flutter_tools/lib/src/resident_web_runner.dart
118	    // for the web initialization and server logic.
119	    final String url = platformArgs['uri'] as String;
120	    final bool launchChrome = platformArgs['no-launch-chrome'] != true;
121	    if (launchChrome) {
122	      _chrome = await chromeLauncher.launch(
123	        url,
124	        cacheDir: _fileSystem.currentDirectory
125	            .childDirectory('.dart_tool')
126	            .childDirectory('chrome-device'),
127	        headless: debuggingOptions.webRunHeadless,
128	        debugPort: debuggingOptions.webBrowserDebugPort,
129	      );
130	    }
131	
132	    _logger.sendEvent('app.webLaunchUrl', <String, dynamic>{'url': url, 'launched': launchChrome});
133	    return LaunchResult.succeeded(observatoryUri: url != null ? Uri.parse(url): null);
134	  }
135	
136	  @override
137	  Future<bool> stopApp(ApplicationPackage app) async {
138	    await _chrome?.close();
139	    return true;
140	  }
141	
142	  @override
143	  Future<TargetPlatform> get targetPlatform async => TargetPlatform.web_javascript;
144	
145	  @override
146	  Future<bool> uninstallApp(ApplicationPackage app) async => true;
147	
148	  @override
149	  bool isSupportedForProject(FlutterProject flutterProject) {
150	    return flutterProject.web.existsSync();
151	  }
152	
153	  @override
154	  Future<void> dispose() async {
155	    _logReader?.dispose();
156	    await portForwarder?.dispose();
157	  }
158	}
