20	/// An environment variable used to override the location of Google Chrome.
21	const String kChromeEnvironment = 'CHROME_EXECUTABLE';
22	
23	/// An environment variable used to override the location of Microsoft Edge.
24	const String kEdgeEnvironment = 'EDGE_ENVIRONMENT';
25	
26	/// The expected executable name on linux.
27	const String kLinuxExecutable = 'google-chrome';
28	
29	/// The expected executable name on macOS.
30	const String kMacOSExecutable =
31	    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
32	
33	/// The expected Chrome executable name on Windows.
34	const String kWindowsExecutable = r'Google\Chrome\Application\chrome.exe';
35	
36	/// The expected Edge executable name on Windows.
37	const String kWindowsEdgeExecutable = r'Microsoft\Edge\Application\msedge.exe';
38	
39	typedef BrowserFinder = String Function(Platform, FileSystem);
40	
41	/// Find the chrome executable on the current platform.
42	///
43	/// Does not verify whether the executable exists.
44	String findChromeExecutable(Platform platform, FileSystem fileSystem) {
45	  if (platform.environment.containsKey(kChromeEnvironment)) {
46	    return platform.environment[kChromeEnvironment];
47	  }
48	  if (platform.isLinux) {
49	    return kLinuxExecutable;
50	  }
51	  if (platform.isMacOS) {
52	    return kMacOSExecutable;
53	  }
54	  if (platform.isWindows) {
55	    /// The possible locations where the chrome executable can be located on windows.
56	    final List<String> kWindowsPrefixes = <String>[
57	      platform.environment['LOCALAPPDATA'],
58	      platform.environment['PROGRAMFILES'],
59	      platform.environment['PROGRAMFILES(X86)'],
60	    ];
61	    final String windowsPrefix = kWindowsPrefixes.firstWhere((String prefix) {
62	      if (prefix == null) {
63	        return false;
64	      }
65	      final String path = fileSystem.path.join(prefix, kWindowsExecutable);
66	      return fileSystem.file(path).existsSync();
67	    }, orElse: () => '.');
68	    return fileSystem.path.join(windowsPrefix, kWindowsExecutable);
69	  }
70	  throwToolExit('Platform ${platform.operatingSystem} is not supported.');
71	  return null;
72	}
